function ProductCard({ p, addToCart }) {
  return (
    <div className="card">
      <img src={p.image} alt="" />

      <div className="card-body">
        <h4>{p.name}</h4>

        <p className="price">
          {Number(p.price).toLocaleString()}₫
        </p>

        <button onClick={() => addToCart(p)}>
          🛒 Thêm vào giỏ
        </button>
      </div>
    </div>
  );
}

export default ProductCard;
